    {
        events.ScheduleEvent(EVENT_FROSTBOLT, 1 * IN_MILLISECONDS);
        events.ScheduleEvent(EVENT_FREEZING_CIRCLE, 8.5 * IN_MILLISECONDS);
        events.ScheduleEvent(EVENT_BLIZZARD, 16 * IN_MILLISECONDS);
    }

